from typing import List, Union
from functools import reduce

def mean_absolute_deviation(numbers: List[float]) -> Union[float, str]:
    if any(isinstance(x, str) for x in numbers):
        return 'Error'
    n = len(numbers)
    if n == 0:
        return 'Error'
    mean = sum(numbers) / n
    abs_diff_sum = reduce(lambda acc, x: acc + abs(x - mean), numbers, 0)
    mad = abs_diff_sum / n
    return str(mad)

def monotonic(l):
    # Helper to check duplicates without loops or sorting:
    def has_duplicates(seq):
        if len(seq) < 2:
            return False
        first, rest = seq[0], seq[1:]
        if first in rest:
            return True
        return has_duplicates(rest)

    # Helper to check strictly increasing:
    def strictly_increasing(seq):
        if len(seq) < 2:
            return True
        return seq[0] < seq[1] and strictly_increasing(seq[1:])

    # Helper to check strictly decreasing:
    def strictly_decreasing(seq):
        if len(seq) < 2:
            return True
        return seq[0] > seq[1] and strictly_decreasing(seq[1:])

    if isinstance(l, str):
        # For strings: 
        # Return False if duplicates,
        # else True and original string if strictly increasing (alphabetical) or decreasing (reverse alphabetical),
        # else False.
        if has_duplicates(l):
            return False
        if strictly_increasing(l) or strictly_decreasing(l):
            return True, l
        return False
    else:
        # For lists:
        # Return False if duplicates,
        # else True if strictly increasing or strictly decreasing,
        # else False.
        # According to user's clarifications, return only True or False (not a tuple).
        if has_duplicates(l):
            return False
        if strictly_increasing(l) or strictly_decreasing(l):
            return True
        return False

from collections import Counter

def search(lst):
    if not lst:
        return -1
    # Check if the list contains strings
    if isinstance(lst[0], str):
        return max(lst)
    # For integers: frequency condition
    freq = Counter(lst)
    # The valid candidates are those integers x where freq[x] >= x and x > 0
    # Return the greatest such integer or -1 if none
    candidates = [x for x in freq if x > 0 and freq[x] >= x]
    return str(max(candidates)) if candidates else "-1"

def total_match(lst1, lst2):
    # Helper to detect if list contains any string elements
    def contains_str(lst):
        return any(isinstance(x, str) for x in lst)

    # Helper to sum total length of string elements in a list
    def total_str_len(lst):
        return sum(len(x) for x in lst if isinstance(x, str))

    # Helper to sum total digits of int elements in a list
    def total_digit_len(lst):
        return sum(len(str(abs(x))) for x in lst if isinstance(x, int))

    # Determine if any list contains strings
    lst1_has_str = contains_str(lst1)
    lst2_has_str = contains_str(lst2)

    # Both empty lists => return empty string as per examples
    if not lst1 and not lst2:
        return ""

    if lst1_has_str or lst2_has_str:
        # Compare total length of string elements in each list
        t1 = total_str_len(lst1)
        t2 = total_str_len(lst2)
        # If both zero (i.e. no strings), treat them as zero length
        # If equal or lst1 longer => return lst1
        # else return lst2
        if t1 >= t2:
            chosen = lst1
        else:
            chosen = lst2
    else:
        # Both lists contain only ints (or empty)
        # Compare total digits count
        t1 = total_digit_len(lst1)
        t2 = total_digit_len(lst2)
        if t1 <= t2:
            chosen = lst1
        else:
            chosen = lst2

    # Sort chosen list ascending
    chosen_sorted = sorted(chosen, key=lambda x: (x if isinstance(x, int) else 0))

    # Then reorder to maintain original order but ascending order too:
    # "The order of the output list must be in ascending order but at the same time maintain its original order."
    # This is contradictory. The best interpretation is:
    # The output list must be ascending, but if duplicates or equal elements appear, their relative order is preserved.
    # Python's sorted is stable, so no further action needed.
    # Actually the above sorts integers ascending, strings treated as 0 (since strings and ints mixed?)
    # The spec doesn't clarify mixed lists with strings and ints for sorting.
    # But since if strings appear, the function returns entire list containing strings (not mixed?),
    # so this should not happen. So when strings are present, sorting is just lexicographic ascending.
    # Let's handle sorting properly for both cases:

    if chosen and isinstance(chosen[0], str):
        # Sort strings ascending
        chosen_sorted = sorted(chosen)
    elif chosen and all(isinstance(x, int) for x in chosen):
        chosen_sorted = sorted(chosen)
    else:
        # Mixed or empty: fallback to sorted as is (should not happen per problem statement)
        chosen_sorted = list(chosen)

    # Return as string separated by space
    return " ".join(str(x) for x in chosen_sorted)

def count_upper(s):
    vowels = {'A', 'E', 'I', 'O', 'U'}
    count = 0
    if len(s) > 0 and s[0] in vowels:
        count += 1
    if len(s) > 2 and s[2] in vowels:
        count += 1
    if len(s) > 4 and s[4] in vowels:
        count += 1
    # Convert count to binary string without using bin()
    if count == 0:
        return '0'
    if count == 1:
        return '1'
    # Since O(1) complexity and no loops, max count is 3 (indices 0,2,4)
    if count == 2:
        return '10'
    if count == 3:
        return '11'

def digits(n):
    s = str(n)
    # Extract odd digits and convert to ints
    odd_digits = [int(d) for d in s if int(d) % 2 == 1]
    if not odd_digits:
        return 0
    prod = 1
    for d in odd_digits:
        prod *= d
    return prod

def sum_squares(lst):
    def ceiling(x):
        int_x = int(x)
        return int_x if x == int_x else (int_x + 1 if x > 0 else int_x)

    # filter out floats by checking type, keep only ints
    filtered = list(filter(lambda v: isinstance(v, int), lst))
    # map each int to its ceiling (which is the number itself since it's int)
    # then square and sum using sum() which is allowed (not an explicit loop)
    result = sum(map(lambda x: ceiling(x)**2, filtered))
    return str(result)

def order_by_points(nums):
    if not nums:
        return []
    # Helper to sum digits of absolute integer value
    def digit_sum(x):
        return sum(map(int, str(abs(int(x)))))
    # Sort by digit sum, stable so original order preserved when sums equal
    sorted_nums = sorted(nums, key=digit_sum)
    return ', '.join(str(x) for x in sorted_nums)
